# 🟢 低风险：只读/信息收集，通常无副作用
#!/bin/bash
# pod-diagnose.sh - Pod 诊断脚本

POD_NAME=${1:-}
NAMESPACE=${2:-default}

if [ -z "$POD_NAME" ]; then
    echo "Usage: $0 <pod-name> [namespace]"
    exit 1
fi

echo "=========================================="
echo "Pod 诊断报告: $POD_NAME"
echo "命名空间: $NAMESPACE"
echo "=========================================="

echo -e "\n[1] Pod 基本信息"
kubectl get pod "$POD_NAME" -n "$NAMESPACE" -o wide

echo -e "\n[2] Pod 详细状态"
kubectl get pod "$POD_NAME" -n "$NAMESPACE" -o jsonpath='
状态: {.status.phase}
节点: {.spec.nodeName}
IP: {.status.podIP}
QoS: {.status.qosClass}
启动时间: {.status.startTime}
'
echo ""

echo -e "\n[3] 容器状态"
kubectl get pod "$POD_NAME" -n "$NAMESPACE" -o jsonpath='
{range .status.containerStatuses[*]}
容器: {.name}
  镜像: {.image}
  就绪: {.ready}
  重启次数: {.restartCount}
  状态: {.state}
{end}
'

echo -e "\n[4] 资源配置"
kubectl get pod "$POD_NAME" -n "$NAMESPACE" -o jsonpath='
{range .spec.containers[*]}
容器: {.name}
  Requests: CPU={.resources.requests.cpu}, Memory={.resources.requests.memory}
  Limits: CPU={.resources.limits.cpu}, Memory={.resources.limits.memory}
{end}
'

echo -e "\n[5] 事件记录"
kubectl get events -n "$NAMESPACE" --field-selector=involvedObject.name="$POD_NAME" --sort-by='.lastTimestamp'

echo -e "\n[6] 日志 (最近 50 行)"
kubectl logs "$POD_NAME" -n "$NAMESPACE" --tail=50 2>/dev/null || echo "无法获取日志"

echo -e "\n[7] 描述信息"
kubectl describe pod "$POD_NAME" -n "$NAMESPACE"
